package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TreeTraversingParser_getLongValue_TriageGen2Test {

    private ObjectMapper mapper;
    private JsonNodeFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = JsonNodeFactory.instance;
    }

    /**
     * Tests getLongValue when the current node is a valid LongNumericNode.
     */
    @Test
    public void testGetLongValue_Success() throws IOException {
        // Arrange
        long expectedValue = 123456789L;
        ObjectNode root = factory.objectNode();
        root.putLong("value", expectedValue);

        // We need to simulate the parser being at the numeric node.
        // Since TreeTraversingParser is a wrapper around a JsonNode, 
        // we create a parser that traverses this node.
        TreeTraversingParser parser = new TreeTraversingParser(root);

        // Move to the field "value"
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME ("value")
        parser.nextToken(); // VALUE_NUMBER_INT (123456789)

        // Act
        long actualValue = parser.getLongValue();

        // Assert
        Assert.assertEquals(expectedValue, actualValue);
    }

    /**
     * Tests getLongValue when the current node is a DoubleNumericNode.
     * Jackson's NumericNode.longValue() performs a narrowing primitive conversion.
     */
    @Test
    public void testGetLongValue_FromDouble() throws IOException {
        // Arrange
        double expectedValue = 123.45;
        long expectedLong = 123L;
        ObjectNode root = factory.objectNode();
        root.put(123.45);

        TreeTraversingParser parser = new TreeTraversingParser(root);
        parser.nextToken(); // VALUE_NUMBER_FLOAT

        // Act
        long actualValue = parser.getLongValue();

        // Assert
        Assert.assertEquals(expectedLong, actualValue);
    }

    /**
     * Tests getLongValue when the current node is a BigIntegerNumericNode.
     */
    @Test
    public void testGetLongValue_FromBigInteger() throws IOException {
        // Arrange
        java.math.BigInteger bigIntValue = java.math.BigInteger.valueOf(987654321L);
        ObjectNode root = factory.objectNode();
        root.put(bigIntValue);

        TreeTraversingParser parser = new TreeTraversingParser(root);
        parser.nextToken(); // VALUE_NUMBER_INT

        // Act
        long actualValue = parser.getLongValue();

        // Assert
        Assert.assertEquals(bigIntValue.longValue(), actualValue);
    }

    /**
     * Tests getLongValue when the current node is not a NumericNode.
     * This tests the casting behavior in (NumericNode) currentNumericNode().
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_ThrowsClassCastException() throws IOException {
        // Arrange
        ObjectNode root = factory.objectNode();
        root.put("notANumber");

        TreeTraversingParser parser = new TreeTraversingParser(root);
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // VALUE_STRING

        // Act
        parser.getLongValue();
    }

    /**
     * Tests getLongValue when the parser is at EOF or null.
     * Depending on implementation, currentNumericNode() might throw IOException or NPE.
     */
    @Test(expected = Exception.class)
    public void testGetLongValue_NullNode() throws IOException {
        // Arrange
        ObjectNode root = factory.objectNode();
        TreeTraversingParser parser = new TreeTraversingParser(root);
        // No nextToken() called, current node is null/not set

        // Act
        parser.getLongValue();
    }
}
